changeSet.sql:
DROP PROCEDURE IF EXISTS BT.SP_GET_RESULT(
    IN UUID, OUT REFCURSOR, OUT TEXT, OUT TEXT, OUT TEXT
);
DROP PROCEDURE IF EXISTS BT.SP_GET_RESULT_BY_STRATEGY(
    IN UUID, IN INTEGER, OUT REFCURSOR, OUT TEXT, OUT TEXT, OUT TEXT
);

changeSet.rollback:
DROP PROCEDURE IF EXISTS BT.SP_GET_RESULT(
    IN UUID, IN UUID, IN INTEGER, OUT REFCURSOR, OUT TEXT, OUT TEXT, OUT TEXT
);

changeSet.sql:
DO $$
BEGIN
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'quant_app') THEN
        GRANT EXECUTE ON PROCEDURE BT.SP_GET_RESULT(
            IN UUID, IN UUID, IN INTEGER,
            OUT REFCURSOR, OUT TEXT, OUT TEXT, OUT TEXT
        ) TO quant_app;
    END IF;
END $$;
